      </div>
      <Modal
        modal={modal}
        exportData={exportData}
        setExportData={setExportData}
        title={title}
        setTitle={setTitle}
        setModal={setModal}
        importFrom={importFrom}
        importDb={importDb}
        saveAsCopy={saveAsCopy}
        fitToView={fitToView}
        onBack={
          openedFromStart
            ? () => {
                setModal(MODAL.NONE);
                onBackToStart();
              }
            : undefined
        }
      />
      <Sidesheet
        type={sidesheet}
        title={title}
        setTitle={setTitle}
        onClose={() => setSidesheet(SIDESHEET.NONE)}
      />
      <ConfigureCustomTypes
        open={modal === MODAL.CONFIG_CUSTOM_TYPES}
        onClose={() => setModal(MODAL.NONE)}
      />
      <SemiModal
        title={t("auto_connect_fk_modal_title")}
        centered
        visible={showAutoConnectModal}
        onOk={confirmAutoConnectFKs}
        onCancel={() => setShowAutoConnectModal(false)}
        okText={t("auto_connect_fk")}
        cancelText={t("cancel")}
      >
        <div className="space-y-3">
          <p className="text-sm">{t("auto_connect_fk_modal_description")}</p>
          <ol className="list-decimal ps-5 space-y-1 text-sm">
            <li>{t("auto_connect_fk_rule_1")}</li>
            <li>{t("auto_connect_fk_rule_2")}</li>
          </ol>
          <p className="text-sm font-medium mt-2">
            {t("auto_connect_fk_modal_question")}
          </p>
        </div>
      </SemiModal>
    </>
  );

  function toolbar() {
    return (
      <div
        className="py-1.5 px-3 flex items-center gap-1 rounded-xl select-none overflow-hidden toolbar-theme shadow-lg"
        style={isRtl(i18n.language) ? { direction: "rtl" } : {}}
      >
        <div className="flex justify-start items-center">
          <LayoutDropdown />
          <Divider layout="vertical" margin="8px" />
          <Tooltip content={t("zoom_out")} position="bottom">
            <button
              className="py-1 px-2 hover-2 rounded-sm text-lg"
              onClick={() =>
                setTransform((prev) => ({ ...prev, zoom: prev.zoom / 1.2 }))
              }
            >
              <i className="fa-solid fa-magnifying-glass-minus" />
            </button>
          </Tooltip>
          <Dropdown
            style={{ width: "240px" }}
            position={isRtl(i18n.language) ? "bottomRight" : "bottomLeft"}
            render={
              <Dropdown.Menu
                style={isRtl(i18n.language) ? { direction: "rtl" } : {}}
              >
                <Dropdown.Item
                  onClick={fitWindow}
                  style={{ display: "flex", justifyContent: "space-between" }}
                >
                  <div>{t("fit_window_reset")}</div>
                  <div className="text-gray-400">Ctrl+Alt+W</div>
                </Dropdown.Item>
                <Dropdown.Divider />
                {[0.25, 0.5, 0.75, 1.0, 1.25, 1.5, 2.0, 3.0].map((e, i) => (
                  <Dropdown.Item
                    key={i}
                    onClick={() => {
                      setTransform((prev) => ({ ...prev, zoom: e }));
                    }}
                  >
                    {Math.floor(e * 100)}%
                  </Dropdown.Item>
                ))}
                <Dropdown.Divider />
                <Dropdown.Item>
                  <InputNumber
                    field="zoom"
                    label={t("zoom")}
                    placeholder={t("zoom")}
                    suffix={<div className="p-1">%</div>}
                    onChange={(v) =>
                      setTransform((prev) => ({
                        ...prev,
                        zoom: parseFloat(v) * 0.01,
                      }))
                    }
                  />
                </Dropdown.Item>
              </Dropdown.Menu>
            }
            trigger="click"
          >
            <div className="py-1 px-2 hover-2 rounded-sm flex items-center justify-center">
              <div className="w-[40px]">
                {Math.floor(transform.zoom * 100)}%
              </div>
              <div>
                <IconCaretdown />
              </div>
            </div>
          </Dropdown>
          <Tooltip content={t("zoom_in")} position="bottom">
            <button
              className="py-1 px-2 hover-2 rounded-sm text-lg"
              onClick={() =>
                setTransform((prev) => ({ ...prev, zoom: prev.zoom * 1.2 }))
              }
            >
              <i className="fa-solid fa-magnifying-glass-plus" />
            </button>
          </Tooltip>
          <Divider layout="vertical" margin="8px" />
          <Tooltip content={t("undo")} position="bottom">
            <button
              className="py-1 px-2 hover-2 rounded-sm flex items-center disabled:opacity-50"
              disabled={undoStack.length === 0 || layout.readOnly}
              onClick={undo}
            >
              <IconUndo size="large" />
            </button>
          </Tooltip>
          <Tooltip content={t("redo")} position="bottom">
            <button
              className="py-1 px-2 hover-2 rounded-sm flex items-center disabled:opacity-50"
              disabled={redoStack.length === 0 || layout.readOnly}
              onClick={redo}
            >
              <IconRedo size="large" />
            </button>
          </Tooltip>
          <Divider layout="vertical" margin="8px" />
          <Tooltip content={t("add_table")} position="bottom">
            <button
              className="flex items-center py-1 px-2 hover-2 rounded-sm disabled:opacity-50"
              onClick={() => addTable()}
              disabled={layout.readOnly}
            >
              <IconAddTable />
            </button>
          </Tooltip>
          <Tooltip content={t("add_view")} position="bottom">
            <button
              className="flex items-center py-1 px-2 hover-2 rounded-sm disabled:opacity-50"
              disabled={true}
            >
              <IconAddView />
            </button>
          </Tooltip>
          <Tooltip content={t("add_area")} position="bottom">
            <button
              className="py-1 px-2 hover-2 rounded-sm flex items-center disabled:opacity-50"
              onClick={() => addArea()}
              disabled={layout.readOnly}
            >
              <IconAddArea />
            </button>
          </Tooltip>
          <Tooltip content={t("add_note")} position="bottom">
            <button
              className="py-1 px-2 hover-2 rounded-sm flex items-center disabled:opacity-50"
              onClick={() => addNote()}
              disabled={layout.readOnly}
            >
              <IconAddNote />
            </button>
          </Tooltip>
          <Divider layout="vertical" margin="8px" />
          <Dropdown
            trigger="custom"
            visible={arrangeMenuOpen}
            onClickOutSide={() => setArrangeMenuOpen(false)}
            position={isRtl(i18n.language) ? "bottomRight" : "bottomLeft"}
            disabled={layout.readOnly}
            render={
              <Dropdown.Menu
                style={isRtl(i18n.language) ? { direction: "rtl" } : {}}
              >
                <Dropdown.Title>{t("auto_arrange")}</Dropdown.Title>
                {layoutEngines.map((engine) => (
                  <Dropdown.Item
                    key={engine.id}
                    onClick={() => {
                      setArrangeMenuOpen(false);
                      autoArrangeTables(engine.id);
                    }}
                  >
                    {t(`layout_${engine.id}`)}
                  </Dropdown.Item>
                ))}
              </Dropdown.Menu>
            }
          >
            <button
              className="py-1 px-2 hover-2 rounded-sm text-xl -mt-0.5 disabled:opacity-50"
              disabled={layout.readOnly}
              title={t("auto_arrange")}
              onClick={() => setArrangeMenuOpen((open) => !open)}
            >
              <i className="fa-solid fa-wand-magic-sparkles" />
            </button>
          </Dropdown>
          <Divider layout="vertical" margin="8px" />
          <Tooltip content={t("save")} position="bottom">
            <button
              className="py-1 px-2 hover-2 rounded-sm flex items-center disabled:opacity-50"
              disabled={true} onClick={undefined}

            >
              <IconSaveStroked size="extra-large" />
            </button>
          </Tooltip>
          <Divider layout="vertical" margin="8px" />
          <Tooltip content={t("versions")} position="bottom">
            <button
              className="py-1 px-2 hover-2 rounded-sm text-xl -mt-0.5"
              disabled={true}
            >
              <i className="fa-solid fa-code-branch" />
            </button>
          </Tooltip>
          <Divider layout="vertical" margin="8px" />
          <Tooltip content={t("theme")} position="bottom">
            <button
              className="py-1 px-2 hover-2 rounded-sm text-xl -mt-0.5"
              onClick={() => {
                const body = document.body;
                if (body.hasAttribute("theme-mode")) {
                  if (body.getAttribute("theme-mode") === "light") {
                    menu["view"]["theme"].children[1].function();
                  } else {
                    menu["view"]["theme"].children[0].function();
                  }
                }
              }}
            >
              <i className="fa-solid fa-circle-half-stroke" />
            </button>
          </Tooltip>
        </div>
      </div>
    );
  }

  function getState() {
    switch (saveState) {
      case State.NONE:
        return "Transient session · not saved";
      case State.LOADING:
        return t("loading");
      case State.SAVED:
        return `${t("last_saved")} ${lastSaved}`;
      case State.SAVING:
        return t("saving");
      case State.ERROR:
        return t("failed_to_save");
      case State.FAILED_TO_LOAD:
        return t("failed_to_load");
      default:
        return "";
    }
  }

  function header() {
    return (
      <nav
        className="flex justify-between pt-1 items-center whitespace-nowrap"
        style={isRtl(i18n.language) ? { direction: "rtl" } : {}}
      >
        <div className="flex justify-start items-center">
          <Link to="/">
            <img
              width={54}
              src={icon}
              alt={t("logo")}
              className="ms-7 min-w-[54px]"
            />
          </Link>
          <div className="ms-1 mt-1">
            <div className="flex items-center ms-3 gap-2">
              {databases[database].image && (
                <img
                  src={databases[database].image}
                  className="h-5"
                  style={{
                    filter:
                      "opacity(0.4) drop-shadow(0 0 0 white) drop-shadow(0 0 0 white)",
                  }}
                  alt={t("database_icon", {
                    databaseName: databases[database].name,
                  })}
                  title={t("database_diagram", {
                    databaseName: databases[database].name,
                  })}
                />
              )}
              <Slot name="diagram-title-prefix" />
              <div
                className="text-xl flex items-center gap-1 me-1"
                onPointerEnter={(e) => e.isPrimary && setShowEditName(true)}
                onPointerLeave={(e) => e.isPrimary && setShowEditName(false)}
                onPointerDown={(e) => {
                  // Required for onPointerLeave to trigger when a touch pointer leaves
                  // https://stackoverflow.com/a/70976017/1137077
                  e.target.releasePointerCapture(e.pointerId);
                }}
                onClick={!layout.readOnly && (() => setModal(MODAL.RENAME))}
              >
                <span>{isTemplate ? t("templates") : t("diagrams")}</span>
                <span className="select-none text-zinc-400 dark:text-zinc-500 mx-1">
                  /
                </span>
                <span>{title}</span>
                {version && (
                  <Tag className="mt-1" color="blue" size="small">
                    {version.substring(0, 7)}
                  </Tag>
                )}
              </div>
              {(showEditName || modal === MODAL.RENAME) && !layout.readOnly && (
                <IconEdit />
              )}
            </div>
            <div className="flex items-center">
              <div className="flex justify-start text-md select-none me-2">
                {Object.keys(menu).map((category) => (
                  <Dropdown
                    key={category}
                    position="bottomLeft"
                    onVisibleChange={(visible) => {
                      const tagged = Object.keys(menu[category]).filter(
                        (item) =>
                          (menu[category][item].is_new ||
                            menu[category][item].children?.some(
                              (child) => child.is_new,
                            )) &&
                          !seenMenuTags.has(item),
                      );
                      if (visible || !tagged.length) return;
                      const next = new Set([...seenMenuTags, ...tagged]);
                      setSeenMenuTags(next);
                      try {
                        localStorage.setItem(
                          "drawdb:seenMenuTags",
                          JSON.stringify([...next]),
                        );
                      } catch {
                        return;
                      }
                    }}
                    style={{
                      width: "240px",
                      direction: isRtl(i18n.language) ? "rtl" : "ltr",
                    }}
                    render={
                      <Dropdown.Menu className="menu max-h-[calc(100vh-80px)] overflow-auto">
                        {Object.keys(menu[category]).map((item, index) => {
                          if (menu[category][item].children) {
                            return (
                              <Dropdown
                                className="min-w-36 max-w-72"
                                key={item}
                                position="rightTop"
                                render={
                                  <Dropdown.Menu>
                                    {menu[category][item].children.map(
                                      (e, i) => {
                                        if (e.divider) {
                                          return (
                                            <Dropdown.Divider
                                              key={`divider-${i}`}
                                            />
                                          );
                                        }
                                        return (
                                          <Dropdown.Item
                                            key={i}
                                            onClick={e.function}
                                            className="flex w-full items-center justify-between gap-1"
                                            disabled={e.disabled}
                                          >
                                            <span className="truncate flex-1 min-w-0">
                                              {e.name}
                                            </span>
                                            {e.label && (
                                              <Tag
                                                size="small"
                                                className="flex-shrink-0"
                                              >
                                                {e.label}
                                              </Tag>
                                            )}
                                            {e.is_new && (
                                              <Tag
                                                size="small"
                                                color="blue"
                                                className="flex-shrink-0"
                                              >
                                                {t("new")}
                                              </Tag>
                                            )}
                                          </Dropdown.Item>
                                        );
                                      },
                                    )}
                                  </Dropdown.Menu>
                                }
                              >
                                <Dropdown.Item
                                  style={{
                                    display: "flex",
                                    justifyContent: "space-between",
                                    alignItems: "center",
                                  }}
                                  onClick={menu[category][item].function}
                                >
                                  <span className="flex items-center gap-2">
                                    {t(item)}
                                    {menu[category][item].is_new && (
                                      <Tag size="small" color="blue">
                                        {t("new")}
                                      </Tag>
                                    )}
                                  </span>

                                  {isRtl(i18n.language) ? (
                                    <IconChevronLeft />
                                  ) : (
                                    <IconChevronRight />
                                  )}
                                </Dropdown.Item>
                              </Dropdown>
                            );
                          }
                          if (
                            menu[category][item].warning &&
                            !menu[category][item].disabled
                          ) {
                            return (
                              <Popconfirm
                                key={index}
                                title={menu[category][item].warning.title}
                                content={menu[category][item].warning.message}
                                onConfirm={menu[category][item].function}
                                position="right"
                                okText={t("confirm")}
                                cancelText={t("cancel")}
                              >
                                <Dropdown.Item>{t(item)}</Dropdown.Item>
                              </Popconfirm>
                            );
                          }
                          return (
                            <Dropdown.Item
                              key={index}
                              disabled={menu[category][item].disabled}
                              onClick={menu[category][item].function}
                              style={
                                menu[category][item].shortcut && {
                                  display: "flex",
                                  justifyContent: "space-between",
                                  alignItems: "center",
                                }
                              }
                            >
                              <div className="w-full flex items-center justify-between">
                                <div className="flex items-center gap-2">
                                  {t(item)}
                                  {menu[category][item].is_new && (
                                    <Tag size="small" color="blue">
                                      {t("new")}
                                    </Tag>
                                  )}
                                </div>
                                <div className="flex items-center gap-1">
                                  {menu[category][item].shortcut && (
                                    <div className="text-gray-400">
                                      {menu[category][item].shortcut}
                                    </div>
                                  )}
                                  {menu[category][item].state &&
                                    menu[category][item].state}
                                </div>
                              </div>
                            </Dropdown.Item>
                          );
                        })}
                      </Dropdown.Menu>
                    }
                  >
                    <div className="px-3 py-1 hover-2 rounded-sm">
                      {Object.keys(menu[category]).some(
                        (item) =>
                          (menu[category][item].is_new ||
                            menu[category][item].children?.some(
                              (child) => child.is_new,
                            )) &&
                          !seenMenuTags.has(item),
                      ) ? (
                        <Badge
                          dot
                          type="primary"
                          countStyle={{ right: -7, top: 5 }}
                        >
                          {t(category)}
                        </Badge>
                      ) : (
                        t(category)
                      )}
                    </div>
                  </Dropdown>
                ))}
              </div>
              {layout.readOnly && <Tag size="small">{t("read_only")}</Tag>}
              {!layout.readOnly && (
                <Tag
                  size="small"
                  type="light"
                  prefixIcon={
                    saveState === State.LOADING ||
                    saveState === State.SAVING ? (
                      <Spin size="small" />
                    ) : null
                  }
                >
                  {getState()}
                </Tag>
              )}
            </div>
          </div>
        </div>
      </nav>
    );
  }
}

src/components/EditorHeader/LayoutDropdo:
import {
  IconCaretdown,
  IconCheckboxTick,
  IconRowsStroked,
} from "@douyinfe/semi-icons";
import { Dropdown } from "@douyinfe/semi-ui";
import { useFullscreen, useLayout } from "../../hooks";
import { enterFullscreen, exitFullscreen } from "../../utils/fullscreen";
import { useTranslation } from "react-i18next";
import { isRtl } from "../../i18n/utils/rtl";
import i18n from "../../i18n/i18n";

export default function LayoutDropdown() {
  const fullscreen = useFullscreen();
  const { layout, setLayout } = useLayout();
  const { t } = useTranslation();

  const invertLayout = (component) =>
    setLayout((prev) => ({ ...prev, [component]: !prev[component] }));

  return (
    <Dropdown
      position="bottomLeft"
      style={{
        width: "180px",
        direction: isRtl(i18n.language) ? "rtl" : "ltr",
      }}
      render={
        <Dropdown.Menu>
          <Dropdown.Title>{t("view")}</Dropdown.Title>
          <Dropdown.Item
            icon={
              layout.header ? <IconCheckboxTick /> : <div className="px-2" />
            }
            onClick={() => invertLayout("header")}
          >
            {t("header")}
          </Dropdown.Item>
          <Dropdown.Item
            icon={
              layout.sidebar ? <IconCheckboxTick /> : <div className="px-2" />
            }
            onClick={() => invertLayout("sidebar")}
          >
            {t("sidebar")}
          </Dropdown.Item>
          <Dropdown.Item
            icon={
              layout.issues ? <IconCheckboxTick /> : <div className="px-2" />
            }
            onClick={() => invertLayout("issues")}
          >
            {t("issues")}
          </Dropdown.Item>
          <Dropdown.Divider />
          <Dropdown.Item
            icon={fullscreen ? <IconCheckboxTick /> : <div className="px-2" />}
            onClick={() => {
              if (fullscreen) {
                exitFullscreen();
              } else {
                enterFullscreen();
              }
            }}
          >
            {t("fullscreen")}
          </Dropdown.Item>
        </Dropdown.Menu>
      }
      trigger="click"
    >
      <div className="py-1 px-2 hover-2 rounded-sm flex items-center justify-center">
        <IconRowsStroked size="extra-large" />
        <div>
          <IconCaretdown />
        </div>
      </div>
    </Dropdown>
  );
}

src/components/EditorHeader/Modal/Import:
import {
  Banner,
  Button,
  Checkbox,
  TabPane,
  Tabs,
  Upload,
} from "@douyinfe/semi-ui";
import { Fragment, useState } from "react";
import { IconCopy, IconDownload, IconTickCircle } from "@douyinfe/semi-icons";
import { saveAs } from "file-saver";
import { useTranslation } from "react-i18next";
import { STATUS } from "../../../data/constants";
import { databases } from "../../../data/databases";
import {
  useAreas,
  useDiagram,
  useNotes,
  useSettings,
  useViews,
} from "../../../hooks";
import { schemaQueries } from "../../../utils/importFrom/schemaQuery";
import CodeEditor from "../../CodeEditor";

export default function ImportDatabase({
  importData,
  setImportData,
  error,
  setError,
  sourceDb,
}) {
  const { t } = useTranslation();
  const { query, minVersion, cli, note } = schemaQueries[sourceDb];
  const editorHeight = Math.max(320, window.innerHeight - 480);
  const { tables } = useDiagram();
  const { notes } = useNotes();
  const { areas } = useAreas();
  const { views } = useViews();
  const { settings } = useSettings();
  const [cliCopied, setCliCopied] = useState(false);
  const isEmpty =
    !tables.length && !notes.length && !areas.length && !views.length;

  const setSchema = (schema) => {
    setImportData((prev) => ({ ...prev, schema }));
    setError({ type: STATUS.NONE, message: "" });
  };

  return (
    <div className="space-y-1">
      <div className="text-sm">
        {t("schema_query_instructions", { database: databases[sourceDb].name })}
        <div className="opacity-70 mt-1">
          {t("requires_version", { version: minVersion })}
          {note && ` ${t(note)}`}
        </div>
      </div>
      <div className="grid grid-cols-2 gap-4">
        <Tabs>
          <TabPane tab={t("query")} itemKey="query">
            <CodeEditor
              height={editorHeight}
              language="sql"
              value={query}
              options={{ readOnly: true, minimap: { enabled: false } }}
              formatOnMount={false}
              showCopyButton
              extraControls={
                <Button
                  icon={<IconDownload />}
                  aria-label={t("download")}
                  onClick={() =>
                    saveAs(
                      new Blob([query], { type: "text/plain" }),
                      "drawdb-schema.sql",
                    )
                  }
                />
              }
            />
          </TabPane>
        </Tabs>
        <Tabs>
          <TabPane tab={t("paste_result")} itemKey="paste">
            <CodeEditor
              height={editorHeight}
              language="json"
              value={importData.schema}
              options={{ minimap: { enabled: false } }}
              formatOnMount={false}
              onChange={(value) => setSchema(value ?? "")}
            />
          </TabPane>
          <TabPane tab={t("upload_file")} itemKey="upload">
            <div
              className="flex flex-col gap-3"
              style={{ height: editorHeight }}
            >
              <div className="text-sm">
                <div className="mb-2">{t("schema_query_large")}</div>
                <div
                  className={`flex items-center gap-3 rounded-lg border px-4 py-3 ${
                    settings.mode === "dark"
                      ? "border-zinc-800 bg-zinc-700"
                      : "border-zinc-200 bg-zinc-100"
                  }`}
                >
                  <pre
                    className={`min-w-0 flex-1 whitespace-pre-wrap font-mono text-sm ${
                      settings.mode === "dark"
                        ? "text-zinc-200"
                        : "text-zinc-800"
                    }`}
                  >
                    <span className="mr-2 select-none text-zinc-400">&gt;</span>
                    {cli.split(" ").map((part, i) => (
                      <Fragment key={i}>
                        {i > 0 && " "}
                        <span className="whitespace-nowrap">{part}</span>
                      </Fragment>
                    ))}
                  </pre>
                  <button
                    type="button"
                    aria-label={t("copy")}
                    onClick={() =>
                      navigator.clipboard.writeText(cli).then(() => {
                        setCliCopied(true);
                        setTimeout(() => setCliCopied(false), 1500);
                      })
                    }
                    className={`inline-flex h-7 w-7 shrink-0 items-center justify-center rounded-md transition-colors ${
                      settings.mode === "dark"
                        ? "text-zinc-400 hover:bg-zinc-800 hover:text-zinc-200"
                        : "text-zinc-500 hover:bg-zinc-200 hover:text-zinc-700"
                    }`}
                  >
                    {cliCopied ? <IconTickCircle /> : <IconCopy />}
                  </button>
                </div>
              </div>
              <Upload
                className="min-h-0 flex-1 !flex !flex-col !flex-nowrap [&_.semi-upload-drag-area]:min-h-0 [&_.semi-upload-drag-area]:flex-1 [&_.semi-upload-file-list]:!h-auto [&_.semi-upload-file-list]:!flex-none"
                action="#"
                beforeUpload={({ file, fileList }) => {
                  const f = fileList[0].fileInstance;
                  if (!f) return;
                  const reader = new FileReader();
                  reader.onload = (e) => setSchema(e.target.result);
                  reader.readAsText(f);
                  return {
                    autoRemove: false,
                    fileInstance: file.fileInstance,
                    status: "success",
                    shouldUpload: false,
                  };
                }}
                draggable
                dragMainText={t("drag_and_drop_files")}
                dragSubText={t("upload_query_result")}
                accept=".json,.txt"
                onRemove={() => setSchema("")}
                limit={1}
              />
            </div>
          </TabPane>
        </Tabs>
      </div>
      {!isEmpty && (
        <Checkbox
          aria-label={t("overwrite_checkbox")}
          checked={importData.overwrite}
          onChange={(e) =>
            setImportData((prev) => ({ ...prev, overwrite: e.target.checked }))
          }
        >
          {t("overwrite_existing_diagram")}
        </Checkbox>
      )}
      {error.type === STATUS.ERROR && (
        <Banner
          type="danger"
          fullMode={false}
          description={<div>{error.message}</div>}
        />
      )}
    </div>
  );
}

import {
  ddbDiagramIsValid,
  jsonDiagramIsValid,
} from "../../../utils/validateSchema";
import { Upload, Banner } from "@douyinfe/semi-ui";
import { DB, IMPORT_FROM, STATUS } from "../../../data/constants";
import {
  useAreas,
  useEnums,
  useNotes,
  useDiagram,
  useTypes,
  useViews,
} from "../../../hooks";
import { useTranslation } from "react-i18next";
import { fromDBML } from "../../../utils/importFrom/dbml";

export default function ImportDiagram({
  setImportData,
  error,
  setError,
  importFrom,
}) {
  const { areas } = useAreas();
  const { notes } = useNotes();
  const { tables, relationships, database } = useDiagram();
  const { types } = useTypes();
  const { enums } = useEnums();
  const { views } = useViews();
  const { t } = useTranslation();

  const diagramIsEmpty = () => {
    return (
      tables.length === 0 &&
      relationships.length === 0 &&
      notes.length === 0 &&
      areas.length === 0 &&
      types.length === 0 &&
      enums.length === 0 &&
      views.length === 0
    );
  };

  const loadJsonData = (file, e) => {
    let jsonObject = null;
    try {
      jsonObject = JSON.parse(e.target.result);
    } catch (error) {
      setError({
        type: STATUS.ERROR,
        message: t("file_contains_error"),
      });
      return;
    }

    if (file.type === "application/json") {
      if (!jsonDiagramIsValid(jsonObject)) {
        setError({
          type: STATUS.ERROR,
          message: t("file_missing_diagram_properties"),
        });
        return;
      }
    } else if (file.name.split(".").pop() === "ddb") {
      if (!ddbDiagramIsValid(jsonObject)) {
        setError({
          type: STATUS.ERROR,
          message: t("file_missing_diagram_properties"),
        });
        return;
      }
    }

    if (!jsonObject.database) {
      jsonObject.database = DB.GENERIC;
    }

    if (jsonObject.database !== database) {
      setError({
        type: STATUS.ERROR,
        message: t("imported_diagram_database_mismatch"),
      });
      return;
    }

    let ok = true;
    jsonObject.relationships.forEach((rel) => {
      const startTable = jsonObject.tables.find(
        (t) => t.id === rel.startTableId,
      );
      const endTable = jsonObject.tables.find((t) => t.id === rel.endTableId);

      if (!startTable || !endTable) {
        setError({
          type: STATUS.ERROR,
          message: t("relationship_references_missing_table", {
            relationshipName: rel.name,
          }),
        });
        ok = false;
        return;
      }

      if (
        !startTable.fields.find((f) => f.id === rel.startFieldId) ||
        !endTable.fields.find((f) => f.id === rel.endFieldId)
      ) {
        setError({
          type: STATUS.ERROR,
          message: t("relationship_references_missing_field", {
            relationshipName: rel.name,
          }),
        });
        ok = false;
        return;
      }
    });

    if (!ok) return;

    setImportData(jsonObject);
    if (diagramIsEmpty()) {
      setError({
        type: STATUS.OK,
        message: t("ready_to_import"),
      });
    } else {
      setError({
        type: STATUS.WARNING,
        message: t("import_will_overwrite_current"),
      });
    }
  };

  const loadDBMLData = (e) => {
    try {
      setImportData(fromDBML(e.target.result, database));
    } catch (error) {
      const message = t("parse_error_at", {
        name: error.diags[0].name,
        line: error.diags[0].location.start.line,
        column: error.diags[0].location.start.column,
        message: error.diags[0].message,
      });

      setError({ type: STATUS.ERROR, message });
    }
  };

  const getAcceptableFileTypes = () => {
    switch (importFrom) {
      case IMPORT_FROM.JSON:
        return "application/json,.ddb";
      case IMPORT_FROM.DBML:
        return ".dbml";
      default:
        return "";
    }
  };

  const getDragSubText = () => {
    switch (importFrom) {
      case IMPORT_FROM.JSON:
        return `${t("supported_types")} JSON, DDB`;
      case IMPORT_FROM.DBML:
        return `${t("supported_types")} DBML`;
      default:
        return "";
    }
  };

  return (
    <div>
      <Upload
        action="#"
        beforeUpload={({ file, fileList }) => {
          const f = fileList[0].fileInstance;
          if (!f) {
            return;
          }
          const reader = new FileReader();
          reader.onload = async (e) => {
            if (importFrom == IMPORT_FROM.JSON) loadJsonData(f, e);
            if (importFrom == IMPORT_FROM.DBML) loadDBMLData(e);
          };
          reader.readAsText(f);

          return {
            autoRemove: false,
            fileInstance: file.fileInstance,
            status: "success",
            shouldUpload: false,
          };
        }}
        draggable={true}
        dragMainText={t("drag_and_drop_files")}
        dragSubText={getDragSubText()}
        accept={getAcceptableFileTypes()}
        onRemove={() =>
          setError({
            type: STATUS.NONE,
            message: "",
          })
        }
        onFileChange={() =>
          setError({
            type: STATUS.NONE,
            message: "",
          })
        }
        limit={1}
      />
      {error.type === STATUS.ERROR ? (
        <Banner
          type="danger"
          fullMode={false}
          description={<div>{error.message}</div>}
        />
      ) : error.type === STATUS.OK ? (
        <Banner
          type="info"
          fullMode={false}
          description={<div>{error.message}</div>}
        />
      ) : (
        error.type === STATUS.WARNING && (
          <Banner
            type="warning"
            fullMode={false}
            description={<div>{error.message}</div>}
          />
        )
      )}
    </div>
  );
}

