import {
  Button,
  Image,
  Input,
  Modal as SemiUIModal,
  Spin,
  Toast,
} from "@douyinfe/semi-ui";
import { saveAs } from "file-saver";
import { Parser } from "node-sql-parser";
import { Parser as OracleParser } from "oracle-sql-parser";
import { useEffect, useState } from "react";
import { useTranslation } from "react-i18next";
import { DB, MODAL, STATUS } from "../../../data/constants";
import { databases } from "../../../data/databases";
import {
  useAreas,
  useDiagram,
  useEnums,
  useNavigateWithParams,
  useNotes,
  useSettings,
  useTransform,
  useTypes,
  useUndoRedo,
  useViews,
} from "../../../hooks";
import { isRtl } from "../../../i18n/utils/rtl";
import { useExtensions } from "../../../context/ExtensionsContext";
import { importSQL } from "../../../utils/importSQL";
import { fromSchemaQuery } from "../../../utils/importFrom/schemaQuery";
import { autoArrange } from "../../../utils/autoArrange";
import { getTableHeight } from "../../../utils/utils";
import {
  allowedTypesFor,
  normalizeAiDiagram,
} from "../../../utils/importAiDiagram";
import {
  getModalTitle,
  getModalWidth,
  getOkText,
} from "../../../utils/modalData";
import CodeEditor from "../../CodeEditor";
import ImportDatabase from "./ImportDatabase";
import ImportDiagram from "./ImportDiagram";
import ImportSource from "./ImportSource";
import ImportWithAiButton from "./ImportWithAiButton";
import Language from "./Language";
import Open from "./Open";
import Rename from "./Rename";
import Share from "./Share";
import { mergeCustomTypes } from "../../../utils/customTypes";

const extensionToLanguage = {
  md: "markdown",
  sql: "sql",
  dbml: "dbml",
  json: "json",
};

export default function Modal({
  modal,
  setModal,
  title,
  setTitle,
  exportData,
  setExportData,
  importDb,
  importFrom,
  saveAsCopy,
  fitToView,
  onBack,
}) {
  const { t, i18n } = useTranslation();
  const { tables, setTables, setRelationships, database, setSqlHeader } =
    useDiagram();
  const { setNotes } = useNotes();
  const { setAreas } = useAreas();
  const { setTypes } = useTypes();
  const { setEnums } = useEnums();
  const { setViews } = useViews();
  const { setTransform } = useTransform();
  const { setUndoStack, setRedoStack } = useUndoRedo();
  const { settings } = useSettings();
  const [uncontrolledTitle, setUncontrolledTitle] = useState(title);
  const [uncontrolledLanguage, setUncontrolledLanguage] = useState(
    i18n.language,
  );
  const [importSource, setImportSource] = useState({
    src: "",
    schema: "",
    overwrite: false,
  });
  const [importData, setImportData] = useState(null);
  const [error, setError] = useState({
    type: STATUS.NONE,
    message: "",
  });
  const [selectedDiagramId, setSelectedDiagramId] = useState(0);
  const [saveAsTitle, setSaveAsTitle] = useState(title);
  const [aiImporting, setAiImporting] = useState(false);
  const navigate = useNavigateWithParams();
  const { importSqlWithAi } = useExtensions();

  useEffect(() => {
    if (modal === MODAL.SAVEAS) setSaveAsTitle(title);
  }, [modal, title]);

  const overwriteDiagram = () => {
    setTables(importData.tables);
    setRelationships(importData.relationships);
    setAreas(importData.subjectAreas ?? []);
    setNotes(importData.notes ?? []);
    setViews(importData.views ?? []);
    if (importData.title) {
      setTitle(importData.title);
    }
    if (databases[database].hasEnums && importData.enums) {
      setEnums(importData.enums);
    }
    if (databases[database].hasTypes && importData.types) {
      setTypes(importData.types);
    }
    if (importData.customTypes) {
      mergeCustomTypes(importData.customTypes);
    }
    setSqlHeader(importData.sqlHeader ?? "");
  };

  const parseSQLAndLoadDiagram = () => {
    const targetDatabase = database === DB.GENERIC ? importDb : database;

    let ast = null;
    try {
      if (targetDatabase === DB.ORACLESQL) {
        const oracleParser = new OracleParser();

        ast = oracleParser.parse(importSource.src);
      } else {
        const parser = new Parser();

        ast = parser.astify(importSource.src, {
          database: targetDatabase,
        });
      }
    } catch (error) {
      const message = error.location
        ? t("parse_error_at", {
            name: error.name,
            line: error.location.start.line,
            column: error.location.start.column,
            message: error.message,
          })
        : error.message;

      setError({ type: STATUS.ERROR, message });
      return;
    }

    try {
      const diagramData = importSQL(
        ast,
        database === DB.GENERIC ? importDb : database,
        database,
      );

      applyImportedDiagram(diagramData);
    } catch (e) {
      setError({
        type: STATUS.ERROR,
        message: t("check_syntax_errors"),
      });
    }
  };

  // arrangeImported lays out the imported tables with auto arrange. When the
  // person adds the import to an existing diagram, we place the new tables
  // below the tables already there.
  const arrangeImported = (diagramData) => {
    const importedTop =
      !importSource.overwrite && tables.length > 0
        ? Math.max(
            ...tables.map(
              (table) => table.y + getTableHeight(table, settings.showComments),
            ),
          ) + 110
        : 0;
    const importedLeft =
      !importSource.overwrite && tables.length > 0
        ? Math.min(...tables.map((table) => table.x))
        : 0;
    const arrangedPositions = new Map(
      autoArrange(diagramData.tables, diagramData.relationships, settings).map(
        (p) => [p.id, p],
      ),
    );
    return {
      ...diagramData,
      tables: diagramData.tables.map((table) => {
        const position = arrangedPositions.get(table.id);
        return position
          ? {
              ...table,
              x: importedLeft + position.x,
              y: importedTop + position.y,
            }
          : table;
      }),
    };
  };

  const applyImportedDiagram = (importedData) => {
    const diagramData = arrangeImported(importedData);
    if (importSource.overwrite) {
      setTables(diagramData.tables);
      setRelationships(diagramData.relationships);
      if (databases[database].hasTypes) setTypes(diagramData.types ?? []);
      if (databases[database].hasEnums) setEnums(diagramData.enums ?? []);
      setTransform((prev) => ({ ...prev, pan: { x: 0, y: 0 } }));
      setNotes([]);
      setAreas([]);
      setViews([]);
    } else {
      setTables((prev) => [...prev, ...diagramData.tables]);
      setRelationships((prev) =>
        [...prev, ...diagramData.relationships].map((r, i) => ({
          ...r,
          id: i,
        })),
      );
      if (databases[database].hasTypes && diagramData.types.length)
        setTypes((prev) => [...prev, ...diagramData.types]);
      if (databases[database].hasEnums && diagramData.enums.length)
        setEnums((prev) => [...prev, ...diagramData.enums]);
    }

    setUndoStack([]);
    setRedoStack([]);
    if (diagramData.tables.length) {
      fitToView(
        importSource.overwrite
          ? diagramData.tables
          : [...tables, ...diagramData.tables],
      );
    }

    setModal(MODAL.NONE);
  };

  const importSourceWithAi = async () => {
    setAiImporting(true);
    try {
      const result = await importSqlWithAi({
        sql: importSource.src,
        database: database === DB.GENERIC ? importDb : database,
        allowedTypes: allowedTypesFor(database),
      });

      if (!result) return;

      const { diagram, warnings } = normalizeAiDiagram(
        result.diagram,
        database,
      );
      const allWarnings = [...(result.warnings ?? []), ...warnings];

      applyImportedDiagram(diagram);

      if (allWarnings.length) {
        Toast.warning({
          content: allWarnings.slice(0, 3).join(" "),
          duration: 8,
        });
      }
    } catch (e) {
      setError({
        type: STATUS.ERROR,
        message: e?.message || t("ai_import_failed"),
      });
    } finally {
      setAiImporting(false);
    }
  };

  const getModalOnOk = async () => {
    switch (modal) {
      case MODAL.IMG:
        saveAs(
          exportData.data,
          `${exportData.filename}.${exportData.extension}`,
        );
        return;
      case MODAL.CODE: {
        const blob = new Blob([exportData.data], {
          type: "application/json",
        });
        saveAs(blob, `${exportData.filename}.${exportData.extension}`);
        return;
      }
      case MODAL.IMPORT:
        if (error.type !== STATUS.ERROR) {
          setTransform((prev) => ({ ...prev, pan: { x: 0, y: 0 } }));
          overwriteDiagram();
          setImportData(null);
          setModal(MODAL.NONE);
          setUndoStack([]);
          setRedoStack([]);
        }
        return;
      case MODAL.IMPORT_SRC:
        parseSQLAndLoadDiagram();
        return;
      case MODAL.IMPORT_DB: {
        let imported;
        try {
          imported = fromSchemaQuery(importSource.schema, database);
        } catch (e) {
          setError({
            type: STATUS.ERROR,
            message: t(
              e.message === "truncated"
                ? "truncated_query_result"
                : "invalid_query_result",
            ),
          });
          return;
        }

        applyImportedDiagram(imported);

        const skipped = ["views", "indexes", "checks"]
          .filter((key) => imported.skipped[key] > 0)
          .map((key) =>
            t(`import_db_${key}`, { count: imported.skipped[key] }),
          );
        Toast.success({
          content: [
            t("import_db_summary", {
              tables: t("import_db_tables", { count: tables.length }),
              relationships: t("import_db_relationships", {
                count: imported.relationships.length,
              }),
            }),
            skipped.length
              ? t("import_db_skipped", { items: skipped.join(", ") })
              : "",
          ].join(" "),
          duration: 6,
        });
        return;
      }
      case MODAL.OPEN:
        if (!selectedDiagramId) return;
        navigate(`/editor/diagrams/${selectedDiagramId}`, "_blank");
        setModal(MODAL.NONE);
        return;
      case MODAL.RENAME:
        setTitle(uncontrolledTitle);
        setModal(MODAL.NONE);
        return;
      case MODAL.SAVEAS:
        await saveAsCopy(saveAsTitle);
        setModal(MODAL.NONE);
        return;
      case MODAL.LANGUAGE:
        i18n.changeLanguage(uncontrolledLanguage);
        setModal(MODAL.NONE);
        return;
      default:
        setModal(MODAL.NONE);
        return;
    }
  };

  const getModalBody = () => {
    switch (modal) {
      case MODAL.IMPORT:
        return (
          <ImportDiagram
            setImportData={setImportData}
            error={error}
            setError={setError}
            importFrom={importFrom}
          />
        );
      case MODAL.IMPORT_SRC:
        return (
          <ImportSource
            importData={importSource}
            setImportData={setImportSource}
            error={error}
            setError={setError}
          />
        );
      case MODAL.IMPORT_DB:
        return (
          <ImportDatabase
            importData={importSource}
            setImportData={setImportSource}
            error={error}
            setError={setError}
            sourceDb={database === DB.GENERIC ? importDb : database}
          />
        );
      case MODAL.RENAME:
        return (
          <Rename key={title} title={title} setTitle={setUncontrolledTitle} />
        );
      case MODAL.OPEN:
        return (
          <Open
            selectedDiagramId={selectedDiagramId}
            setSelectedDiagramId={setSelectedDiagramId}
          />
        );
      case MODAL.SAVEAS:
        return (
          <Input
            placeholder={t("name")}
            value={saveAsTitle}
            onChange={(v) => setSaveAsTitle(v)}
          />
        );
      case MODAL.CODE:
      case MODAL.IMG:
        if (exportData.data !== "" || exportData.data) {
          return (
            <>
              {modal === MODAL.IMG ? (
                <Image
                  src={exportData.data}
                  alt={t("coordinate_space_diagram")}
                  height={280}
                />
              ) : (
                <CodeEditor
                  height={360}
                  value={exportData.data}
                  language={extensionToLanguage[exportData.extension]}
                  options={{ readOnly: true }}
                  showCopyButton={true}
                />
              )}
              <div className="text-sm font-semibold mt-2">{t("filename")}:</div>
              <Input
                value={exportData.filename}
                placeholder={t("filename")}
                suffix={<div className="p-2">{`.${exportData.extension}`}</div>}
                onChange={(value) =>
                  setExportData((prev) => ({ ...prev, filename: value }))
                }
                field="filename"
              />
            </>
          );
        } else {
          return (
            <div className="text-center my-3 text-sky-600">
              <Spin tip={t("loading")} size="large" />
            </div>
          );
        }
      case MODAL.LANGUAGE:
        return (
          <Language
            language={uncontrolledLanguage}
            setLanguage={setUncontrolledLanguage}
          />
        );
      case MODAL.SHARE:
        return <Share title={title} setModal={setModal} />;
      default:
        return <></>;
    }
  };

  const handleCancel = () => {
    if (modal === MODAL.RENAME) setUncontrolledTitle(title);
    if (modal === MODAL.LANGUAGE) setUncontrolledLanguage(i18n.language);
    setModal(MODAL.NONE);
  };

  const okDisabled =
    (error && error?.type === STATUS.ERROR) ||
    (modal === MODAL.IMPORT && (error.type === STATUS.ERROR || !importData)) ||
    (modal === MODAL.RENAME && title === "") ||
    ((modal === MODAL.IMG || modal === MODAL.CODE) && !exportData.data) ||
    (modal === MODAL.SAVEAS && saveAsTitle === "") ||
    (modal === MODAL.IMPORT_SRC && importSource.src === "") ||
    (modal === MODAL.IMPORT_DB && !importSource.schema.trim());

  const showAiFooter =
    modal === MODAL.IMPORT_SRC && typeof importSqlWithAi === "function";

  const footer = (
    <div className="flex items-center justify-between">
      <div className="flex items-center gap-2">
        {onBack && (
          <Button type="tertiary" onClick={onBack}>
            {t("back")}
          </Button>
        )}
        {showAiFooter && error.type === STATUS.ERROR && (
          <ImportWithAiButton
            loading={aiImporting}
            disabled={!importSource.src}
            onClick={importSourceWithAi}
          />
        )}
      </div>
      <div>
        <Button type="tertiary" autoFocus onClick={handleCancel}>
          {t("cancel")}
        </Button>
        <Button theme="solid" disabled={okDisabled} onClick={getModalOnOk}>
          {getOkText(modal)}
        </Button>
      </div>
    </div>
  );

  return (
    <SemiUIModal
      style={isRtl(i18n.language) ? { direction: "rtl" } : {}}
      title={getModalTitle(modal)}
      visible={modal !== MODAL.NONE && modal !== MODAL.CONFIG_CUSTOM_TYPES}
      onOk={getModalOnOk}
      {...(showAiFooter || onBack ? { footer } : {})}
      afterClose={() => {
        setExportData(() => ({
          data: "",
          extension: "",
          filename: `${title}_${new Date().toISOString()}`,
        }));
        setError({
          type: STATUS.NONE,
          message: "",
        });
        setImportData(null);
        setImportSource({
          src: "",
          schema: "",
          overwrite: false,
        });
      }}
      onCancel={handleCancel}
      centered
      closeOnEsc={true}
      okText={getOkText(modal)}
      okButtonProps={{
        disabled: okDisabled,
        hidden: modal === MODAL.SHARE,
      }}
      hasCancel={modal !== MODAL.SHARE}
      cancelText={t("cancel")}
      width={getModalWidth(modal)}
      bodyStyle={{
        maxHeight: window.innerHeight - 280,
        overflow:
          modal === MODAL.CODE || modal === MODAL.IMG ? "hidden" : "auto",
        direction: "ltr",
      }}
    >
      {getModalBody()}
    </SemiUIModal>
  );
}

