            }))
          }
        />
        <div>
          <Button
            block
            icon={<IconPlus />}
            onClick={() => addNote()}
            disabled={layout.readOnly}
          >
            {t("add_note")}
          </Button>
        </div>
      </div>
      {notes.length <= 0 ? (
        <Empty title={t("no_notes")} text={t("no_notes_text")} />
      ) : (
        <Collapse
          activeKey={selectedElement.open ? `${selectedElement.id}` : ""}
          keepDOM={false}
          lazyRender
          onChange={(activeKey) => {
            setSelectedElement((prev) => ({
              ...prev,
              id: parseInt(activeKey),
              open: true,
            }));
          }}
          accordion
        >
          {notes.map((n, i) => (
            <NoteInfo data={n} key={i} nid={i} />
          ))}
        </Collapse>
      )}
    </>
  );
}

import { useState } from "react";
import { AutoComplete } from "@douyinfe/semi-ui";
import { IconSearch } from "@douyinfe/semi-icons";
import { useNotes } from "../../../hooks";
import { useTranslation } from "react-i18next";

export default function SearchBar({ setActiveKey }) {
  const { notes } = useNotes();
  const [searchText, setSearchText] = useState("");
  const { t } = useTranslation();

  const [filteredResult, setFilteredResult] = useState(
    notes.map((t) => t.title),
  );

  const handleStringSearch = (value) => {
    setFilteredResult(
      notes.map((t) => t.title).filter((i) => i.includes(value)),
    );
  };

  return (
    <AutoComplete
      data={filteredResult}
      value={searchText}
      showClear
      prefix={<IconSearch />}
      placeholder={t("search")}
      emptyContent={<div className="p-3 popover-theme">{t("not_found")}</div>}
      onSearch={(v) => handleStringSearch(v)}
      onChange={(v) => setSearchText(v)}
      onSelect={(v) => {
        const { id } = notes.find((t) => t.title === v);
        setActiveKey(`${id}`);
        document
          .getElementById(`scroll_note_${id}`)
          .scrollIntoView({ behavior: "smooth" });
      }}
      className="w-full"
    />
  );
}

src/components/EditorSidePanel/Relations:
import {
  Row,
  Col,
  Select,
  Button,
  Input,
  Collapse,
  Card,
} from "@douyinfe/semi-ui";
import {
  IconClose,
  IconDeleteStroked,
  IconPlus,
} from "@douyinfe/semi-icons";
import {
  Cardinality,
  Constraint,
  Action,
  ObjectType,
  defaultRelationshipColor,
} from "../../../data/constants";
import { useDiagram, useLayout, useUndoRedo } from "../../../hooks";
import { getRelationshipFields } from "../../../utils/utils";
import ColorPicker from "../ColorPicker";
import { useTranslation } from "react-i18next";
import { useMemo, useRef, useState } from "react";

export default function RelationshipInfo({ data }) {
  const { setUndoStack, setRedoStack } = useUndoRedo();
  const { tables, deleteRelationship, updateRelationship } = useDiagram();
  const { t } = useTranslation();
  const { layout } = useLayout();
  const [editField, setEditField] = useState({});
  const initialColorRef = useRef(data.color ?? defaultRelationshipColor);

  const handleColorPick = (color) => {
    if (layout.readOnly) return;
    setUndoStack((prev) => {
      let undoColor = initialColorRef.current;
      const lastColorChange = prev.findLast(
        (e) =>
          e.element === ObjectType.RELATIONSHIP &&
          e.rid === data.id &&
          e.action === Action.EDIT &&
          e.redo?.color,
      );
      if (lastColorChange) {
        undoColor = lastColorChange.redo.color;
      }

      if (color === undoColor) return prev;

      return [
        ...prev,
        {
          action: Action.EDIT,
          element: ObjectType.RELATIONSHIP,
          component: "self",
          rid: data.id,
          undo: { color: undoColor },
          redo: { color },
          message: t("edit_relationship", {
            refName: data.name,
            extra: "[color]",
          }),
        },
      ];
    });
    setRedoStack([]);
  };

  const startTable = useMemo(
    () => tables.find((tb) => tb.id === data.startTableId),
    [tables, data.startTableId],
  );
  const endTable = useMemo(
    () => tables.find((tb) => tb.id === data.endTableId),
    [tables, data.endTableId],
  );

  const pairs = useMemo(() => getRelationshipFields(data), [data]);

  const startTableName = startTable?.name ?? "";
  const endTableName = endTable?.name ?? "";

  const startFieldOptions = (startTable?.fields ?? []).map((f) => ({
    label: f.name,
    value: f.id,
  }));
  const endFieldOptions = (endTable?.fields ?? []).map((f) => ({
    label: f.name,
    value: f.id,
  }));

  const maxPairs = Math.min(
    startTable?.fields?.length ?? 0,
    endTable?.fields?.length ?? 0,
  );

  const commitPairs = (newPairs, extra = "[fields]") => {
    if (layout.readOnly) return;
    const undo = {
      fields: pairs.map((p) => ({ ...p })),
      startFieldId: data.startFieldId,
      endFieldId: data.endFieldId,
    };
    const redo = {
      fields: newPairs.map((p) => ({ ...p })),
      startFieldId: newPairs[0].startFieldId,
      endFieldId: newPairs[0].endFieldId,
    };
    setUndoStack((prev) => [
      ...prev,
      {
        action: Action.EDIT,
        element: ObjectType.RELATIONSHIP,
        rid: data.id,
        undo,
        redo,
        message: t("edit_relationship", {
          refName: data.name,
          extra,
        }),
      },
    ]);
    setRedoStack([]);
    updateRelationship(data.id, redo);
  };

  const changePairField = (index, side, value) => {
    const newPairs = pairs.map((p, i) =>
      i === index ? { ...p, [`${side}FieldId`]: value } : { ...p },
    );
    commitPairs(newPairs);
  };

  const addPair = () => {
    const newPairs = [
      ...pairs.map((p) => ({ ...p })),
      {
        startFieldId: startTable?.fields?.[0]?.id,
        endFieldId: endTable?.fields?.[0]?.id,
      },
    ];
    commitPairs(newPairs, "[add field]");
  };

  const removePair = (index) => {
    if (pairs.length <= 1) return;
    const newPairs = pairs
      .filter((_, i) => i !== index)
      .map((p) => ({ ...p }));
    commitPairs(newPairs, "[remove field]");
  };

  const swapKeys = () => {
    if (layout.readOnly) return;
    const swappedPairs = pairs.map((p) => ({
      startFieldId: p.endFieldId,
      endFieldId: p.startFieldId,
    }));
    const redo = {
      name: `fk_${endTableName}_${
        endTable?.fields?.find((f) => f.id === data.endFieldId)?.name ?? ""
      }_${startTableName}`,
      startTableId: data.endTableId,
      endTableId: data.startTableId,
      fields: swappedPairs,
      startFieldId: swappedPairs[0].startFieldId,
      endFieldId: swappedPairs[0].endFieldId,
    };
    setUndoStack((prev) => [
      ...prev,
      {
        action: Action.EDIT,
        element: ObjectType.RELATIONSHIP,
        rid: data.id,
        undo: {
          name: data.name,
          startTableId: data.startTableId,
          endTableId: data.endTableId,
          fields: pairs.map((p) => ({ ...p })),
          startFieldId: data.startFieldId,
          endFieldId: data.endFieldId,
        },
        redo,
        message: t("edit_relationship", {
          refName: data.name,
          extra: "[swap keys]",
        }),
      },
    ]);
    setRedoStack([]);
    updateRelationship(data.id, redo);
  };

  const changeCardinality = (value) => {
    if (layout.readOnly) return;

    setUndoStack((prev) => [
      ...prev,
      {
        action: Action.EDIT,
        element: ObjectType.RELATIONSHIP,
        rid: data.id,
        undo: { cardinality: data.cardinality },
        redo: { cardinality: value },
        message: t("edit_relationship", {
          refName: data.name,
          extra: "[cardinality]",
        }),
      },
    ]);
    setRedoStack([]);
    updateRelationship(data.id, { cardinality: value });
  };

  const changeConstraint = (key, value) => {
    if (layout.readOnly) return;

    const undoKey = `${key}Constraint`;
    setUndoStack((prev) => [
      ...prev,
      {
        action: Action.EDIT,
        element: ObjectType.RELATIONSHIP,
        rid: data.id,
        undo: { [undoKey]: data[undoKey] },
        redo: { [undoKey]: value },
        message: t("edit_relationship", {
          refName: data.name,
          extra: "[constraint]",
        }),
      },
    ]);
    setRedoStack([]);
    updateRelationship(data.id, { [undoKey]: value });
  };

  return (
    <>
      <div className="flex items-center mb-2.5">
        <div className="text-md font-semibold break-keep">{t("name")}: </div>
        <Input
          value={data.name}
          validateStatus={data.name.trim() === "" ? "error" : "default"}
          placeholder={t("name")}
          className="ms-2"
          readonly={layout.readOnly}
          onChange={(value) => updateRelationship(data.id, { name: value })}
          onFocus={(e) => setEditField({ name: e.target.value })}
          onBlur={(e) => {
            if (e.target.value === editField.name) return;
            setUndoStack((prev) => [
              ...prev,
              {
                action: Action.EDIT,
                element: ObjectType.RELATIONSHIP,
                component: "self",
                rid: data.id,
                undo: editField,
                redo: { name: e.target.value },
                message: t("edit_relationship", {
                  refName: e.target.value,
                  extra: "[name]",
                }),
              },
            ]);
            setRedoStack([]);
          }}
        />
      </div>
      <div className="flex justify-between items-center mb-1">
        <div className="me-3">
          <span className="font-semibold">{t("primary")}: </span>
          {endTableName}
        </div>
        <div className="mx-1">
          <span className="font-semibold">{t("foreign")}: </span>
          {startTableName}
        </div>
      </div>

      <div className="font-semibold my-1">{t("cardinality")}:</div>
      <Select
        optionList={Object.values(Cardinality).map((v) => ({
          label: t(v),
          value: v,
        }))}
        value={data.cardinality}
        className="w-full"
        onChange={changeCardinality}
      />

      {data.cardinality !== Cardinality.ONE_TO_ONE && (
        <>
          <div className="text-md font-semibold break-keep mt-2">
            {t("many_side_label")}:
          </div>
          <Input
            value={data.manyLabel}
            placeholder={t("label")}
            onChange={(value) => updateRelationship(data.id, { manyLabel: value })}
            onFocus={(e) => setEditField({ manyLabel: e.target.value })}
            readonly={layout.readOnly}
            onBlur={(e) => {
              if (e.target.value === editField.manyLabel) return;
              setUndoStack((prev) => [
                ...prev,
                {
                  action: Action.EDIT,
                  element: ObjectType.RELATIONSHIP,
                  component: "self",
                  rid: data.id,
                  undo: editField,
                  redo: { manyLabel: e.target.value },
                  message: t("edit_relationship", {
                    refName: e.target.value,
                    extra: "[manyLabel]",
                  }),
                },
              ]);
              setRedoStack([]);
            }}
          />
        </>
      )}

      <Row gutter={6} className="my-3">
        <Col span={12}>
          <div className="font-semibold">{t("on_update")}: </div>
          <Select
            optionList={Object.values(Constraint).map((v) => ({
              label: v,
              value: v,
            }))}
            value={data.updateConstraint}
            className="w-full"
            onChange={(value) => changeConstraint("update", value)}
          />
        </Col>
        <Col span={12}>
          <div className="font-semibold">{t("on_delete")}: </div>
          <Select
            optionList={Object.values(Constraint).map((v) => ({
              label: v,
              value: v,
            }))}
            value={data.deleteConstraint}
            className="w-full"
            onChange={(value) => changeConstraint("delete", value)}
          />
        </Col>
      </Row>
      <Card
        bodyStyle={{ padding: "4px" }}
        style={{ marginTop: "12px", marginBottom: "12px" }}
        headerLine={false}
      >
        <Collapse keepDOM={false} lazyRender accordion>
          <Collapse.Panel header={t("composite_key")} itemKey="1">
            <div className="pb-4">
              <div className="text-color opacity-70 mb-3">
                {t("composite_key_hint")}
              </div>
              <div className="grid grid-cols-[1fr_1fr_32px] gap-2 items-center mb-2">
                <div className="text-xs font-semibold text-color">
                  {t("foreign")}
                </div>
                <div className="text-xs font-semibold text-color">
                  {t("primary")}
                </div>
                <div />
              </div>
              {pairs.map((pair, i) => (
                <div
                  key={i}
                  className="grid grid-cols-[1fr_1fr_32px] gap-2 items-center mb-2.5"
                >
                  <Select
                    optionList={startFieldOptions}
                    value={pair.startFieldId}
                    className="w-full"
                    disabled={layout.readOnly}
                    onChange={(value) => changePairField(i, "start", value)}
                  />
                  <Select
                    optionList={endFieldOptions}
                    value={pair.endFieldId}
                    className="w-full"
                    disabled={layout.readOnly}
                    onChange={(value) => changePairField(i, "end", value)}
                  />
                  <Button
                    icon={
                      <IconClose
                        size="small"
                        style={{ color: "var(--semi-color-danger)" }}
                      />
                    }
                    type="tertiary"
                    disabled={layout.readOnly || pairs.length <= 1}
                    onClick={() => removePair(i)}
                  />
                </div>
              ))}
              <Button
                block
                icon={<IconPlus />}
                onClick={addPair}
                disabled={layout.readOnly || pairs.length >= maxPairs}
                className="mt-1"
              >
                {t("add_field")}
              </Button>
            </div>
          </Collapse.Panel>
        </Collapse>
      </Card>

      <div className="flex justify-between items-center gap-1 mt-2 mb-2">
        <ColorPicker
          usePopover={true}
          readOnly={layout.readOnly}
          value={data.color ?? defaultRelationshipColor}
          onChange={(color) => updateRelationship(data.id, { color })}
          onColorPick={(color) => handleColorPick(color)}
        />
        <div className="flex gap-1">
          <Button
            icon={<i className="bi bi-arrow-left-right" />}
            type="tertiary"
            onClick={swapKeys}
            disabled={layout.readOnly}
            title={t("swap")}
          />
          <Button
            type="danger"
            disabled={layout.readOnly}
            icon={<IconDeleteStroked />}
            onClick={() => deleteRelationship(data.id)}
            title={t("delete")}
          />
        </div>
      </div>
    </>
  );
}

import { memo } from "react";
import { Collapse } from "@douyinfe/semi-ui";
import { useSelect, useDiagram, useSaveState, useLayout } from "../../../hooks";
import Empty from "../Empty";
import SearchBar from "./SearchBar";
import RelationshipInfo from "./RelationshipInfo";
import { ObjectType, State } from "../../../data/constants";
import { useTranslation } from "react-i18next";
import { SortableList } from "../../SortableList/SortableList";
import { DragHandle } from "../../SortableList/DragHandle";

export default function RelationshipsTab() {
  const { relationships, setRelationships } = useDiagram();
  const { selectedElement, setSelectedElement } = useSelect();
  const { setSaveState } = useSaveState();
  const { t } = useTranslation();

  return (
    <>
      <SearchBar />
      {relationships.length <= 0 ? (
        <Empty
          title={t("no_relationships")}
          text={t("no_relationships_text")}
        />
      ) : (
        <Collapse
          activeKey={
            selectedElement.open &&
            selectedElement.element === ObjectType.RELATIONSHIP
              ? `${selectedElement.id}`
              : ""
          }
          keepDOM={false}
          lazyRender
          onChange={(k) => {
            setSelectedElement((prev) => ({
              ...prev,
              open: true,
              id: k[0],
              element: ObjectType.RELATIONSHIP,
            }));
          }}
          accordion
        >
          <SortableList
            keyPrefix="relationships-tab"
            items={relationships}
            onChange={(newRelationships) => setRelationships(newRelationships)}
            afterChange={() => setSaveState(State.SAVING)}
            renderItem={renderRelationshipListItem}
          />
        </Collapse>
      )}
    </>
  );
}

const renderRelationshipListItem = (relationship) => (
  <RelationshipListItem relationship={relationship} />
);

const RelationshipListItem = memo(function RelationshipListItem({
  relationship,
}) {
  const { layout } = useLayout();

  return (
    <div id={`scroll_ref_${relationship.id}`}>
      <Collapse.Panel
        className="relative"
        header={
          <div className="w-full flex items-center gap-2">
            <DragHandle readOnly={layout.readOnly} id={relationship.id} />
            <div className="overflow-hidden text-ellipsis whitespace-nowrap">
              {relationship.name}
            </div>
          </div>
        }
        itemKey={`${relationship.id}`}
      >
        <RelationshipInfo data={relationship} />
      </Collapse.Panel>
    </div>
  );
});

import { useState } from "react";
import { useSelect, useDiagram } from "../../../hooks";
import { AutoComplete } from "@douyinfe/semi-ui";
import { IconSearch } from "@douyinfe/semi-icons";
import { ObjectType } from "../../../data/constants";
import { useTranslation } from "react-i18next";

export default function SearchBar() {
  const { relationships } = useDiagram();
  const [searchText, setSearchText] = useState("");
  const { setSelectedElement } = useSelect();
  const { t } = useTranslation();

  const [filteredResult, setFilteredResult] = useState(
    relationships.map((t) => t.name),
  );

  const handleStringSearch = (value) => {
    setFilteredResult(
      relationships.map((t) => t.name).filter((i) => i.includes(value)),
    );
  };

  return (
    <AutoComplete
      data={filteredResult}
      value={searchText}
      showClear
      prefix={<IconSearch />}
      placeholder={t("search")}
      emptyContent={<div className="p-3 popover-theme">{t("not_found")}</div>}
      onSearch={(v) => handleStringSearch(v)}
      onChange={(v) => setSearchText(v)}
