import { useState } from "react";
import { AutoComplete } from "@douyinfe/semi-ui";
import { IconSearch } from "@douyinfe/semi-icons";
import { useSelect, useTypes } from "../../../hooks";
import { ObjectType } from "../../../data/constants";
import { useTranslation } from "react-i18next";

export default function Searchbar() {
  const { types } = useTypes();
  const [value, setValue] = useState("");
  const { setSelectedElement } = useSelect();
  const { t } = useTranslation();

  const [filteredResult, setFilteredResult] = useState(
    types.map((t) => t.name),
  );

  const handleStringSearch = (value) => {
    setFilteredResult(
      types.map((t) => t.name).filter((i) => i.includes(value)),
    );
  };

  return (
    <AutoComplete
      data={filteredResult}
      value={value}
      showClear
      prefix={<IconSearch />}
      placeholder={t("search")}
      onSearch={(v) => handleStringSearch(v)}
      emptyContent={<div className="p-3 popover-theme">{t("not_found")}</div>}
      onChange={(v) => setValue(v)}
      onSelect={(v) => {
        const i = types.findIndex((t) => t.name === v);
        setSelectedElement((prev) => ({
          ...prev,
          id: i,
          open: true,
          element: ObjectType.TYPE,
        }));
        document
          .getElementById(`scroll_type_${i}`)
          .scrollIntoView({ behavior: "smooth" });
      }}
      className="w-full"
    />
  );
}

import { useState } from "react";
import { Action, ObjectType } from "../../../data/constants";
import {
  Row,
  Col,
  Input,
  Button,
  Select,
  TagInput,
  InputNumber,
  Popover,
} from "@douyinfe/semi-ui";
import { IconDeleteStroked, IconMore } from "@douyinfe/semi-icons";
import {
  useUndoRedo,
  useTypes,
  useDiagram,
  useEnums,
  useLayout,
} from "../../../hooks";
import { useTranslation } from "react-i18next";
import { dbToTypes } from "../../../data/datatypes";
import { getCustomTypesForDb, resolveType } from "../../../utils/customTypes";

export default function TypeField({ data, tid, fid }) {
  const { types, updateType } = useTypes();
  const { enums } = useEnums();
  const { layout } = useLayout();
  const { database } = useDiagram();
  const { setUndoStack, setRedoStack } = useUndoRedo();
  const [editField, setEditField] = useState({});
  const { t } = useTranslation();

  return (
    <Row gutter={6} className="hover-1 my-2">
      <Col span={10}>
        <Input
          value={data.name}
          readonly={layout.readOnly}
          validateStatus={data.name === "" ? "error" : "default"}
          placeholder={t("name")}
          onChange={(value) =>
            updateType(tid, {
              fields: types[tid].fields.map((e, id) =>
                id === fid ? { ...data, name: value } : e,
              ),
            })
          }
          onFocus={(e) => setEditField({ name: e.target.value })}
          onBlur={(e) => {
            if (e.target.value === editField.name) return;
            setUndoStack((prev) => [
              ...prev,
              {
                action: Action.EDIT,
                element: ObjectType.TYPE,
                component: "field",
                tid: tid,
                fid: fid,
                undo: editField,
                redo: { name: e.target.value },
                message: t("edit_type", {
                  typeName: data.name,
                  extra: "[field]",
                }),
              },
            ]);
            setRedoStack([]);
          }}
        />
      </Col>
      <Col span={11}>
        <Select
          className="w-full"
          optionList={[
            ...Object.keys(dbToTypes[database]).map((value) => ({
              label: value,
              value: value,
            })),
            ...Object.keys(getCustomTypesForDb(database)).map((value) => ({
              label: value,
              value,
            })),
            ...types
              .filter(
                (type) => type.name.toLowerCase() !== types[tid].name.toLowerCase(),
              )
              .map((type) => ({
                label: type.name.toUpperCase(),
                value: type.name.toUpperCase(),
              })),
            ...enums.map((type) => ({
              label: type.name.toUpperCase(),
              value: type.name.toUpperCase(),
            })),
          ]}
          filter
          value={data.type}
          validateStatus={data.type === "" ? "error" : "default"}
          placeholder={t("type")}
          onChange={(value) => {
            if (layout.readOnly) return;
            if (value === data.type) return;
            setUndoStack((prev) => [
              ...prev,
              {
                action: Action.EDIT,
                element: ObjectType.TYPE,
                component: "field",
                tid: tid,
                fid: fid,
                undo: { type: data?.type },
                redo: { type: value },
                message: t("edit_type", {
                  typeName: data.name,
                  extra: "[field]",
                }),
              },
            ]);
            setRedoStack([]);
            if (value === "ENUM" || value === "SET") {
              updateType(tid, {
                fields: types[tid].fields?.map((e, id) =>
                  id === fid
                    ? {
                        ...data,
                        type: value,
                        values: data.values ? [...data.values] : [],
                      }
                    : e,
                ),
              });
            } else if (
              resolveType(database, value).isSized ||
              resolveType(database, value).hasPrecision
            ) {
              updateType(tid, {
                fields: types[tid].fields.map((e, id) =>
                  id === fid
                    ? {
                        ...data,
                        type: value,
                        size: resolveType(database, value).defaultSize,
                      }
                    : e,
                ),
              });
            } else {
              updateType(tid, {
                fields: types[tid].fields.map((e, id) =>
                  id === fid ? { ...data, type: value } : e,
                ),
              });
            }
          }}
        />
      </Col>
      <Col span={3}>
        <Popover
          content={
            <div className="popover-theme w-[240px]">
              {(data.type === "ENUM" || data.type === "SET") && (
                <>
                  <div className="font-semibold mb-1">
                    {data.type} {t("values")}
                  </div>
                  <TagInput
                    separator={[",", ", ", " ,"]}
                    value={data.values}
                    validateStatus={
                      !data.values || data.values.length === 0
                        ? "error"
                        : "default"
                    }
                    className="my-2"
                    placeholder={t("use_for_batch_input")}
                    onChange={(v) => {
                      if (layout.readOnly) return;
                      updateType(tid, {
                        fields: types[tid].fields.map((e, id) =>
                          id === fid ? { ...data, values: v } : e,
                        ),
                      });
                    }}
                    onFocus={() => setEditField({ values: data.values })}
                    onBlur={() => {
                      if (
                        JSON.stringify(editField.values) ===
                        JSON.stringify(data.values)
                      )
                        return;
                      setUndoStack((prev) => [
                        ...prev,
                        {
                          action: Action.EDIT,
                          element: ObjectType.TYPE,
                          component: "field",
                          tid: tid,
                          fid: fid,
                          undo: editField,
                          redo: { values: data.values },
                          message: t("edit_type", {
                            typeName: data.name,
                            extra: "[field]",
                          }),
                        },
                      ]);
                      setRedoStack([]);
                    }}
                  />
                </>
              )}
              {resolveType(database, data.type).isSized && (
                <>
                  <div className="font-semibold">{t("size")}</div>
                  <InputNumber
                    className="my-2 w-full"
                    placeholder={t("size")}
                    value={data.size}
                    readonly={layout.readOnly}
                    onChange={(value) =>
                      updateType(tid, {
                        fields: types[tid].fields.map((e, id) =>
                          id === fid ? { ...data, size: value } : e,
                        ),
                      })
                    }
                    onFocus={(e) => setEditField({ size: e.target.value })}
                    onBlur={(e) => {
                      if (e.target.value === editField.size) return;
                      setUndoStack((prev) => [
                        ...prev,
                        {
                          action: Action.EDIT,
                          element: ObjectType.TABLE,
                          component: "field",
                          tid: tid,
                          fid: fid,
                          undo: editField,
                          redo: { size: e.target.value },
                          message: t("edit_type", {
                            typeName: data.name,
                            extra: "[field]",
                          }),
                        },
                      ]);
                      setRedoStack([]);
                    }}
                  />
                </>
              )}
              {resolveType(database, data.type).hasPrecision && (
                <>
                  <div className="font-semibold">{t("precision")}</div>
                  <Input
                    className="my-2 w-full"
                    placeholder={t("set_precision")}
                    readonly={layout.readOnly}
                    validateStatus={
                      /^\(\d+,\s*\d+\)$|^$/.test(data.size)
                        ? "default"
                        : "error"
                    }
                    value={data.size}
                    onChange={(value) =>
                      updateType(tid, {
                        fields: types[tid].fields.map((e, id) =>
                          id === fid ? { ...data, size: value } : e,
                        ),
                      })
                    }
                    onFocus={(e) => setEditField({ size: e.target.value })}
                    onBlur={(e) => {
                      if (e.target.value === editField.size) return;
                      setUndoStack((prev) => [
                        ...prev,
                        {
                          action: Action.EDIT,
                          element: ObjectType.TABLE,
                          component: "field",
                          tid: tid,
                          fid: fid,
                          undo: editField,
                          redo: { size: e.target.value },
                          message: t("edit_type", {
                            typeName: data.name,
                            extra: "[field]",
                          }),
                        },
                      ]);
                      setRedoStack([]);
                    }}
                  />
                </>
              )}
              <Button
                block
                type="danger"
                disabled={layout.readOnly}
                icon={<IconDeleteStroked />}
                onClick={() => {
                  setUndoStack((prev) => [
                    ...prev,
                    {
                      action: Action.EDIT,
                      element: ObjectType.TYPE,
                      component: "field_delete",
                      tid: tid,
                      fid: fid,
                      data: data,
                      message: t("edit_type", {
                        typeName: data.name,
                        extra: "[delete field]",
                      }),
                    },
                  ]);
                  updateType(tid, {
                    fields: types[tid].fields.filter((_, k) => k !== fid),
                  });
                }}
              >
                {t("delete")}
              </Button>
            </div>
          }
          showArrow
          trigger="click"
          position="right"
        >
          <Button icon={<IconMore />} type="tertiary" />
        </Popover>
      </Col>
    </Row>
  );
}

import { useState } from "react";
import { Action, ObjectType } from "../../../data/constants";
import {
  Collapse,
  Row,
  Col,
  Input,
  TextArea,
  Button,
  Card,
} from "@douyinfe/semi-ui";
import { IconDeleteStroked, IconPlus } from "@douyinfe/semi-icons";
import { useUndoRedo, useTypes, useDiagram, useLayout } from "../../../hooks";
import TypeField from "./TypeField";
import { useTranslation } from "react-i18next";
import { nanoid } from "nanoid";

export default function TypeInfo({ index, data }) {
  const { layout } = useLayout();
  const { deleteType, updateType } = useTypes();
  const { tables, updateField } = useDiagram();
  const { setUndoStack, setRedoStack } = useUndoRedo();
  const [editField, setEditField] = useState({});
  const { t } = useTranslation();

  // TODO: remove indexes, not a valid case after adding id to types
  const typeId = data.id ?? index;

  return (
    <div id={`scroll_type_${typeId}`}>
      <Collapse.Panel
        header={
          <div className="overflow-hidden text-ellipsis whitespace-nowrap">
            {data.name}
          </div>
        }
        itemKey={`${index}`}
      >
        <div className="flex items-center mb-2.5">
          <div className="text-md font-semibold break-keep">{t("name")}: </div>
          <Input
            value={data.name}
            readonly={layout.readOnly}
            validateStatus={data.name === "" ? "error" : "default"}
            placeholder={t("name")}
            className="ms-2"
            onChange={(value) => {
              updateType(typeId, { name: value });
              tables.forEach((table) => {
                table.fields.forEach((field) => {
                  if (field.type.toLowerCase() === data.name.toLowerCase()) {
                    updateField(table.id, field.id, {
                      type: value.toUpperCase(),
                    });
                  }
                });
              });
            }}
            onFocus={(e) => setEditField({ name: e.target.value })}
            onBlur={(e) => {
              if (e.target.value === editField.name) return;

              const updatedFields = tables.reduce((acc, table) => {
                table.fields.forEach((field, i) => {
                  if (field.type.toLowerCase() === data.name.toLowerCase()) {
                    acc.push({ tid: table.id, fid: i });
                  }
                });
                return acc;
              }, []);

              setUndoStack((prev) => [
                ...prev,
                {
                  action: Action.EDIT,
                  element: ObjectType.TYPE,
                  component: "self",
                  tid: typeId,
                  undo: editField,
                  redo: { name: e.target.value },
                  updatedFields,
                  message: t("edit_type", {
                    typeName: data.name,
                    extra: "[name]",
                  }),
                },
              ]);
              setRedoStack([]);
            }}
          />
        </div>
        {data.fields.map((f, j) => (
          <TypeField key={j} data={f} fid={j} tid={index} />
        ))}
        <Card
          bodyStyle={{ padding: "4px" }}
          style={{ marginTop: "12px", marginBottom: "12px" }}
          headerLine={false}
        >
          <Collapse lazyRender keepDOM={false}>
            <Collapse.Panel header={t("comment")} itemKey="1">
              <TextArea
                field="comment"
                value={data.comment}
                autosize
                readonly={layout.readOnly}
                placeholder={t("comment")}
                rows={1}
                onChange={(value) =>
                  updateType(typeId, { comment: value }, false)
                }
                onFocus={(e) => setEditField({ comment: e.target.value })}
                onBlur={(e) => {
                  if (e.target.value === editField.comment) return;
                  setUndoStack((prev) => [
                    ...prev,
                    {
                      action: Action.EDIT,
                      element: ObjectType.TYPE,
                      component: "self",
                      tid: typeId,
                      undo: editField,
                      redo: { comment: e.target.value },
                      message: t("edit_type", {
                        typeName: data.name,
                        extra: "[comment]",
                      }),
                    },
                  ]);
                  setRedoStack([]);
                }}
              />
            </Collapse.Panel>
          </Collapse>
        </Card>
        <Row gutter={6} className="mt-2">
          <Col span={12}>
            <Button
              icon={<IconPlus />}
              disabled={layout.readOnly}
              onClick={() => {
                const newField = {
                  name: "",
                  type: "",
                  id: nanoid(),
                };
                setUndoStack((prev) => [
                  ...prev,
                  {
                    action: Action.EDIT,
                    element: ObjectType.TYPE,
                    component: "field_add",
                    data: {
                      field: newField,
                      index: data.fields.length,
                    },
                    tid: typeId,
                    message: t("edit_type", {
                      typeName: data.name,
                      extra: "[add field]",
                    }),
                  },
                ]);
                setRedoStack([]);
                updateType(typeId, {
                  fields: [...data.fields, newField],
                });
              }}
              block
            >
              {t("add_field")}
            </Button>
          </Col>
          <Col span={12}>
            <Button
              block
              type="danger"
              disabled={layout.readOnly}
              icon={<IconDeleteStroked />}
              onClick={() => deleteType(typeId)}
            >
              {t("delete")}
            </Button>
          </Col>
        </Row>
      </Collapse.Panel>
    </div>
  );
}

import { Collapse, Button, Popover } from "@douyinfe/semi-ui";
import { IconPlus, IconInfoCircle } from "@douyinfe/semi-icons";
import { useSelect, useDiagram, useTypes, useLayout } from "../../../hooks";
import { DB, ObjectType } from "../../../data/constants";
import Searchbar from "./SearchBar";
import Empty from "../Empty";
import TypeInfo from "./TypeInfo";
import { useTranslation } from "react-i18next";

export default function TypesTab() {
  const { types, addType } = useTypes();
  const { selectedElement, setSelectedElement } = useSelect();
  const { layout } = useLayout();
  const { database } = useDiagram();
  const { t } = useTranslation();

  return (
    <>
      <div className="flex gap-2">
        <Searchbar />
        <div>
          <Button
            block
            icon={<IconPlus />}
            onClick={() => addType()}
            disabled={layout.readOnly}
          >
            {t("add_type")}
          </Button>
        </div>
        {database === DB.GENERIC && (
          <Popover
            content={
              <div className="w-[240px] text-sm space-y-2 popover-theme">
                {t("types_info")
                  .split("\n")
                  .map((line, index) => (
                    <div key={index}>{line}</div>
                  ))}
              </div>
            }
            showArrow
            position="rightTop"
          >
            <Button theme="borderless" icon={<IconInfoCircle />} />
          </Popover>
        )}
      </div>
      {types.length <= 0 ? (
        <Empty title={t("no_types")} text={t("no_types_text")} />
      ) : (
        <Collapse
          activeKey={
            selectedElement.open && selectedElement.element === ObjectType.TYPE
              ? `${selectedElement.id}`
              : ""
          }
          keepDOM={false}
          lazyRender
          onChange={(id) =>
            setSelectedElement((prev) => ({
              ...prev,
              open: true,
              id: parseInt(id),
              element: ObjectType.TYPE,
            }))
          }
          accordion
        >
          {types.map((t, i) => (
            <TypeInfo data={t} key={i} index={i} />
          ))}
        </Collapse>
      )}
    </>
  );
}

