function ViewListItem({ view }) {
  const { updateView } = useViews();
  const { setUndoStack, setRedoStack } = useUndoRedo();
  const { settings } = useSettings();
  const { t } = useTranslation();

  const toggleViewVisibility = (e) => {
    e.stopPropagation();
    setUndoStack((prev) => [
      ...prev,
      {
        action: Action.EDIT,
        element: ObjectType.VIEW,
        component: "self",
        vid: view.id,
        undo: { hidden: view.hidden },
        redo: { hidden: !view.hidden },
        message: t("edit_view", { viewName: view.name, extra: "[hidden]" }),
      },
    ]);
    setRedoStack([]);
    updateView(view.id, { hidden: !view.hidden });
  };

  return (
    <div id={`scroll_view_${view.id}`}>
      <Collapse.Panel
        className="relative"
        header={
          <div className="flex items-center justify-between w-full">
            <div className="flex items-center gap-2 flex-1 min-w-0">
              <div className="overflow-hidden text-ellipsis whitespace-nowrap shrink-0 max-w-[60%]">
                {view.name}
              </div>
              {settings.showComments && view.comment && (
                <div
                  className="overflow-hidden text-ellipsis whitespace-nowrap min-w-0 flex-1 text-xs font-normal opacity-60"
                  title={view.comment}
                >
                  {view.comment}
                </div>
              )}
