            <Button
              size="small"
              theme="borderless"
              type="tertiary"
              onClick={toggleViewVisibility}
              icon={view.hidden ? <IconEyeClosed /> : <IconEyeOpened />}
              className="me-2"
            />
            <div
              className="w-1 h-full absolute top-0 left-0 bottom-0"
              style={{ backgroundColor: view.color }}
            />
          </div>
        }
        itemKey={`${view.id}`}
      >
        <ViewInfo data={view} />
      </Collapse.Panel>
    </div>
  );
}

