import { memo, useRef } from "react";
import {
  closestCenter,
  DndContext,
  PointerSensor,
  useSensor,
  useSensors,
} from "@dnd-kit/core";
import {
  SortableContext,
  arrayMove,
  verticalListSortingStrategy,
} from "@dnd-kit/sortable";
import { SortableItem } from "./SortableItem";

const SortableRow = memo(function SortableRow({ item, index, renderItem }) {
  return <SortableItem id={item.id}>{renderItem(item, index)}</SortableItem>;
});

export function SortableList({
  items,
  onChange,
  afterChange,
  renderItem,
  keyPrefix,
}) {
  const sensors = useSensors(useSensor(PointerSensor));
  const idsRef = useRef([]);

  const ids = items.map((item) => item.id);
  if (
    ids.length !== idsRef.current.length ||
    ids.some((id, i) => id !== idsRef.current[i])
  ) {
    idsRef.current = ids;
  }

  const handleDragEnd = (event) => {
    const { active, over } = event;

    if (active.id !== over.id) {
      const oldIndex = items.findIndex((item) => item.id === active.id);
      const newIndex = items.findIndex((item) => item.id === over.id);
      const newItems = arrayMove(items, oldIndex, newIndex);
      onChange(newItems);
      afterChange();
    }
  };

  return (
    <DndContext
      sensors={sensors}
      collisionDetection={closestCenter}
      onDragEnd={handleDragEnd}
    >
      <SortableContext
        items={idsRef.current}
        strategy={verticalListSortingStrategy}
      >
        {items.map((item, i) => (
          <SortableRow
            key={`${keyPrefix}-sortable-item-${item.id}`}
            item={item}
            index={i}
            renderItem={renderItem}
          />
        ))}
      </SortableContext>
    </DndContext>
  );
}

