import { createContext, useEffect, useState } from "react";
import { useSearchParams } from "react-router-dom";
import { queryConfig } from "../utils/queryConfig";

const defaultSettings = {
  strictMode: false,
  showFieldSummary: true,
  showGrid: true,
  snapToGrid: false,
  showDataTypes: true,
  mode: "light",
  autosave: false,
  showCardinality: true,
  showRelationshipLabels: true,
  showDebugCoordinates: false,
  showComments: false,
};

export const SettingsContext = createContext({
  settings: defaultSettings,
  setSettings: () => {},
});

export default function SettingsContextProvider({ children }) {
  const [searchParams] = useSearchParams();

  const [settings, setSettings] = useState(() => {
    const savedSettings = null;
    let baseSettings = savedSettings
      ? { ...defaultSettings, ...JSON.parse(savedSettings) }
      : defaultSettings;

    const theme = searchParams.get(queryConfig.theme.key);
    if (queryConfig.theme.isValid(theme)) {
      baseSettings = { ...baseSettings, mode: theme };
    }

    return baseSettings;
  });

  useEffect(() => {
    document.body.setAttribute("theme-mode", settings.mode);
  }, [settings.mode]);

  useEffect(() => {
    // no persistent storage
  }, [settings]);

  return (
    <SettingsContext.Provider value={{ settings, setSettings }}>
      {children}
    </SettingsContext.Provider>
  );
}

