          "startFieldId",
          "endTableId",
          "endFieldId",
          "name",
          "cardinality",
          "updateConstraint",
          "deleteConstraint",
          "id",
        ],
      },
    },
    notes: {
      type: "array",
      items: { ...noteSchema },
    },
    subjectAreas: {
      type: "array",
      items: { ...areaSchema },
    },
    types: {
      type: "array",
      items: { ...typeSchema },
    },
    enums: {
      type: "array",
      items: { ...enumSchema },
    },
    views: {
      type: "array",
      items: { ...viewSchema },
    },
    title: { type: "string" },
    database: { type: "string" },
    sqlHeader: { type: "string" },
  },
  required: ["tables", "relationships", "notes", "subjectAreas"],
  additionalProperties: true,
};

export const ddbSchema = {
  type: "object",
  properties: {
    author: { type: "string" },
    project: { type: "string" },
    title: { type: "string" },
    date: { type: "string" },
    ...jsonSchema.properties,
  },
};

